'use strict';

const LEAVE_TIME = '17:16:39';
const leaveImage = new Image();
// Original supplied poster is retained as the background. Its old footer is
// replaced at export; the image contains no selfie or generated person.
leaveImage.src = 'data:image/jpeg;base64,';
function paintLeaveCard(context, date, identity) {
  const target = context.canvas;
  target.width = 1200;
  target.height = Math.round(1200 * leaveImage.naturalHeight / leaveImage.naturalWidth);
  const scale = 1200 / leaveImage.naturalWidth;
  context.drawImage(leaveImage, 0, 0, target.width, target.height);
  const footerY = Math.round(1113 * scale);
  context.fillStyle = '#686868';
  context.fillRect(0, footerY, target.width, target.height - footerY);
  context.save();
  context.font = `bold ${Math.round(28 * scale)}px "Courier New", monospace`;
  context.textBaseline = 'top'; context.fillStyle = '#fff';
  const lines = [
    `NAMA: ${identity.name} | NIPP: ${identity.nipp}`,
    `JABATAN: ${PROFILE.position}`,
    `UPT: ${PROFILE.unit}`,
    'KETERANGAN: LIBUR',
    `WAKTU: ${dateText(date).replace(/, 0(\d) /, ', $1 ')} ${LEAVE_TIME}`
  ];
  lines.forEach((line, i) => context.fillText(line, 22 * scale, (1125 + i * 38) * scale, 1150));
  context.restore();
}
